"""Content-per-platform generator with separately generated images.

Rules encoded here (see PRODUCT-FLOW-SPEC.md):
  * Content and image are produced separately, then composed per platform.
  * Every platform gets its own tone, length and hashtag discipline.
  * Every platform gets its own image size.
  * Images are generated by an image model (DeepSeek cannot generate images at all).
  * BYOK wins: if the caller supplies an image key we never fall back to the server's.
"""
import os
import sys
import json
import base64
import argparse
import urllib.request
import urllib.error
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timedelta, timezone

# ---------------------------------------------------------------- platform rules
PLATFORM_SPECS = {
    "TWITTER": {
        "label": "X / Twitter",
        "max_chars": 280,
        "hashtags": "0-2",
        "tone": "punchy hook in the first 6 words, ONE idea, no preamble, no corporate speak",
        "structure": "hook -> one concrete point -> short question or CTA",
        "image_size": (1600, 900),
        "openai_size": "1536x1024",
    },
    "LINKEDIN": {
        "label": "LinkedIn",
        "max_chars": 1500,
        "hashtags": "3-5",
        "tone": "professional and insight-led, one clear argument, short lines, no hype",
        "structure": "hook -> context -> 3 short bullets -> takeaway -> question",
        "image_size": (1080, 1350),
        "openai_size": "1024x1536",
    },
    "INSTAGRAM": {
        "label": "Instagram",
        "max_chars": 800,
        "hashtags": "5-8",
        "tone": "visual-first, hook line then short scannable body, emoji used sparingly",
        "structure": "hook -> 3 quick value points -> save/share CTA -> hashtags",
        "image_size": (1080, 1350),
        "openai_size": "1024x1536",
    },
}
PLATFORMS = ["TWITTER", "LINKEDIN", "INSTAGRAM"]


def build_prompt(niche, audience, tone, days, pillars, goals, screen_name, persona):
    platform_rules = "\n".join(
        f'  - {p}: max {s["max_chars"]} characters, {s["hashtags"]} hashtags, tone: {s["tone"]}; structure: {s["structure"]}'
        for p, s in PLATFORM_SPECS.items()
    )
    return f"""You are a senior social media strategist producing platform-native content.

BRAND
- Creator screen name: {screen_name or 'the creator'}
- Voice / persona: {persona or 'practical and direct'}
- Niche: {niche}
- Audience: {audience}
- Overall tone: {tone}
- Content pillars to rotate through: {', '.join(pillars) if pillars else 'educational, authority, social proof'}
- Business goals this content serves: {', '.join(goals) if goals else 'audience growth, engagement'}

TASK
Produce a {days}-day content calendar. For EVERY day, produce exactly one post per platform: TWITTER, LINKEDIN, INSTAGRAM.
Each day has its own theme and each day must draw on a DIFFERENT pillar.

PLATFORM RULES (follow exactly - these are hard constraints, not suggestions)
{platform_rules}

IMAGE RULES
- For each post, write "mediaPrompt": a concrete, self-contained description of a single image to generate.
  Describe subject, setting, composition, lighting and style.
- NEVER output image URLs. "mediaUrl" must always be null.

Return ONLY raw valid JSON, no markdown fences, matching:
{{
  "calendarId": "cal_ai_batch",
  "batchStatus": "PENDING_APPROVAL",
  "days": [
    {{
      "dayIndex": 1,
      "date": "YYYY-MM-DD",
      "theme": "theme title",
      "posts": [
        {{"id": "p1_tw", "platform": "TWITTER", "content": "...", "mediaPrompt": "...", "mediaUrl": null, "scheduledTime": "YYYY-MM-DDT14:00:00Z", "status": "PENDING_APPROVAL"}},
        {{"id": "p1_li", "platform": "LINKEDIN", "content": "...", "mediaPrompt": "...", "mediaUrl": null, "scheduledTime": "YYYY-MM-DDT15:30:00Z", "status": "PENDING_APPROVAL"}},
        {{"id": "p1_ig", "platform": "INSTAGRAM", "content": "...", "mediaPrompt": "...", "mediaUrl": null, "scheduledTime": "YYYY-MM-DDT18:00:00Z", "status": "PENDING_APPROVAL"}}
      ]
    }}
  ]
}}"""


def _post_json(url, payload, headers, timeout=90):
    req = urllib.request.Request(
        url, data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json", **headers}, method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def generate_via_openai_compatible(api_key, endpoint, model, prompt):
    res = _post_json(
        endpoint,
        {"model": model,
         "messages": [{"role": "system", "content": "You are a professional social media manager. Output only valid JSON."},
                      {"role": "user", "content": prompt}],
         "response_format": {"type": "json_object"},
         "temperature": 0.7},
        {"Authorization": f"Bearer {api_key}"})
    return json.loads(res["choices"][0]["message"]["content"])


def generate_via_gemini(api_key, model, prompt):
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={api_key}"
    res = _post_json(url, {"contents": [{"parts": [{"text": prompt}]}],
                           "generationConfig": {"temperature": 0.7, "responseMimeType": "application/json"}}, {})
    return json.loads(res["candidates"][0]["content"]["parts"][0]["text"])


# ------------------------------------------------------------------ image models
def generate_image_openai(api_key, prompt, size, out_path, quality="low", model="gpt-image-1"):
    """Generate one image. Returns (ok, detail)."""
    try:
        res = _post_json(
            "https://api.openai.com/v1/images/generations",
            {"model": model, "prompt": prompt, "size": size, "n": 1, "quality": quality},
            {"Authorization": f"Bearer {api_key}"}, timeout=180)
        item = (res.get("data") or [{}])[0]
        raw = None
        if item.get("b64_json"):
            raw = base64.b64decode(item["b64_json"])
        elif item.get("url"):
            with urllib.request.urlopen(item["url"], timeout=120) as r:
                raw = r.read()
        if not raw:
            return False, "no image payload returned"
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_bytes(raw)
        return True, f"{len(raw)} bytes"
    except urllib.error.HTTPError as e:
        return False, f"HTTP {e.code}: {e.read().decode('utf-8', 'ignore')[:220]}"
    except Exception as e:  # noqa: BLE001
        return False, str(e)[:220]


def resize_to_exact(path, target):
    """Resize/crop to the exact platform size when Pillow is available."""
    try:
        from PIL import Image
    except ImportError:
        return False, "Pillow not installed"
    try:
        img = Image.open(path).convert("RGB")
        tw, th = target
        scale = max(tw / img.width, th / img.height)
        img = img.resize((max(1, int(img.width * scale)), max(1, int(img.height * scale))), Image.LANCZOS)
        left = (img.width - tw) // 2
        top = (img.height - th) // 2
        img = img.crop((left, top, left + tw, top + th))
        img.save(path, "PNG")
        return True, f"resized to {tw}x{th}"
    except Exception as e:  # noqa: BLE001
        return False, str(e)[:160]


# ---------------------------------------------------------------------- fallback
def deterministic_calendar(niche, audience, tone, days, pillars, screen_name):
    now = datetime.now(timezone.utc)
    base = now + timedelta(days=1)
    themes = [
        f"The #1 friction point in {niche}",
        f"3 high-leverage systems for {audience}",
        f"What {niche} looks like one year from now",
        f"A hard lesson from building in {niche}",
        f"The boring habit that compounds in {niche}",
        f"Myth vs reality in {niche}",
        f"How to pick your first {niche} project",
    ]
    out_days = []
    for i in range(days):
        cur = base + timedelta(days=i)
        d = cur.strftime("%Y-%m-%d")
        theme = themes[i % len(themes)]
        pillar = (pillars[i % len(pillars)] if pillars else "Educational / how-to")
        posts = []
        for p in PLATFORMS:
            body = (f"{theme}\n\n"
                    f"What actually moves the needle for {audience}:\n"
                    f"1. Cut the work that does not compound\n"
                    f"2. Ship one visible improvement a week\n"
                    f"3. Let the system run before you optimise it\n\n"
                    f"Which one are you doing first?")
            if p == "TWITTER":
                body = body[:275]
            posts.append({
                "id": f"p{i+1}_{p[:2].lower()}",
                "platform": p,
                "content": body,
                "mediaPrompt": f"Clean editorial photograph illustrating '{theme}' for a {niche} brand, natural light, shallow depth of field, modern minimal style",
                "mediaUrl": None,
                "scheduledTime": cur.replace(hour={"TWITTER": 14, "LINKEDIN": 15, "INSTAGRAM": 18}[p], minute=0, second=0).isoformat(),
                "status": "PENDING_APPROVAL",
                "pillar": pillar,
            })
        out_days.append({"dayIndex": i + 1, "date": d, "theme": theme, "posts": posts})
    return {"calendarId": f"cal_{int(now.timestamp())}", "batchStatus": "PENDING_APPROVAL",
            "niche": niche, "audience": audience, "tone": tone,
            "screenName": screen_name, "generatedAt": now.isoformat(), "days": out_days}


# --------------------------------------------------------------------------- main
def main():
    ap = argparse.ArgumentParser(description="Per-platform content + image calendar generator")
    ap.add_argument("--niche", default="AI Productivity & SaaS")
    ap.add_argument("--audience", default="Solopreneurs and creators")
    ap.add_argument("--tone", default="Insightful, practical, engaging")
    ap.add_argument("--provider", default="")
    ap.add_argument("--apiKey", default="")
    ap.add_argument("--days", type=int, default=3)
    ap.add_argument("--pillars", default="")
    ap.add_argument("--goals", default="")
    ap.add_argument("--screenName", default="")
    ap.add_argument("--persona", default="")
    ap.add_argument("--imageProvider", default="")
    ap.add_argument("--imageApiKey", default="")
    ap.add_argument("--imageQuality", default="low")
    ap.add_argument("--imageDir", default="")
    ap.add_argument("--maxImages", type=int, default=6)
    ap.add_argument("--calendarId", default="")
    ap.add_argument("--output", default="")
    args = ap.parse_args()

    days = max(1, min(args.days, 7))  # hard cap: never more than a week in one batch
    pillars = [p for p in args.pillars.split("|") if p]
    goals = [g for g in args.goals.split("|") if g]

    prompt = build_prompt(args.niche, args.audience, args.tone, days, pillars, goals, args.screenName, args.persona)

    calendar = None
    provider_used = None
    try:
        if args.provider == "deepseek" and args.apiKey:
            calendar = generate_via_openai_compatible(
                args.apiKey, "https://api.deepseek.com/chat/completions", "deepseek-chat", prompt)
            provider_used = "deepseek"
        elif args.provider == "openai" and args.apiKey:
            calendar = generate_via_openai_compatible(
                args.apiKey, "https://api.openai.com/v1/chat/completions", "gpt-4o-mini", prompt)
            provider_used = "openai"
        elif args.provider == "gemini" and args.apiKey:
            calendar = generate_via_gemini(args.apiKey, "gemini-1.5-flash", prompt)
            provider_used = "gemini"
    except Exception as e:  # noqa: BLE001
        print(f"[WARN] {args.provider} content call failed: {e}", file=sys.stderr)

    if not calendar:
        calendar = deterministic_calendar(args.niche, args.audience, args.tone, days, pillars, args.screenName)
        provider_used = "deterministic"

    # ---- normalise: platform-native fields, no stray image URLs ----
    for d in calendar.get("days", []):
        for p in d.get("posts", []):
            spec = PLATFORM_SPECS.get(str(p.get("platform", "")).upper())
            if spec:
                p["imageSize"] = f'{spec["image_size"][0]}x{spec["image_size"][1]}'
            p["mediaUrl"] = None  # any URL the model invented is discarded
            p.pop("url", None)

    # The model returns a constant id ("cal_ai_batch"); the server assigns a unique one so a new
    # batch never collides with an existing row (ON CONFLICT DO NOTHING would silently drop it).
    if args.calendarId:
        calendar["calendarId"] = args.calendarId

    calendar["providerUsed"] = provider_used
    calendar["horizonDays"] = days

    # ---- images: generated separately, per platform, per post ----
    image_summary = {"attempted": 0, "generated": 0, "resized": 0, "skipped": 0, "errors": []}
    root = Path(__file__).resolve().parent.parent
    image_dir = Path(args.imageDir) if args.imageDir else (root / "media" / "generated")

    if args.imageApiKey and args.imageProvider:
        targets = []
        for d in calendar.get("days", []):
            for p in d.get("posts", []):
                if p.get("mediaPrompt"):
                    targets.append((d, p))
        image_summary["skipped"] = max(0, len(targets) - args.maxImages)
        targets = targets[:args.maxImages]

        cal_id = str(calendar.get("calendarId") or f"cal_{int(datetime.now(timezone.utc).timestamp())}")

        def one(pair):
            d, p = pair
            spec = PLATFORM_SPECS.get(str(p.get("platform", "")).upper())
            if not spec:
                return None
            name = f'{cal_id}_{d.get("dayIndex")}_{str(p.get("platform")).lower()}_{p.get("id")}.png'.replace("/", "_")
            out = image_dir / cal_id / name
            ok, detail = generate_image_openai(
                args.imageApiKey, p["mediaPrompt"], spec["openai_size"], out,
                quality=args.imageQuality, model=os.environ.get("OPENAI_IMAGE_MODEL", "gpt-image-1"))
            if not ok:
                return ("err", f'{p.get("id")}: {detail}')
            rs_ok, rs_detail = resize_to_exact(out, spec["image_size"])
            p["mediaUrl"] = f'/api/media/generated/{cal_id}/{name}'
            p["imageActualSize"] = f'{spec["image_size"][0]}x{spec["image_size"][1]}' if rs_ok else spec["openai_size"]
            p["imageResized"] = bool(rs_ok)
            return ("ok", rs_detail if rs_ok else "kept api size")

        with ThreadPoolExecutor(max_workers=4) as pool:
            for result in pool.map(one, targets):
                if result is None:
                    continue
                image_summary["attempted"] += 1
                kind, detail = result
                if kind == "ok":
                    image_summary["generated"] += 1
                    if "resized" in detail:
                        image_summary["resized"] += 1
                else:
                    image_summary["errors"].append(detail)

    calendar["imageSummary"] = image_summary

    output_path = Path(args.output) if args.output else (root / ".tmp" / "generated_calendar.json")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(calendar, f, indent=2)

    print(json.dumps(calendar, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
